//! This function generates documentation for the CLI in markdown format,
//! or prints help texts in-app.
//! It takes the outline of the documentation (none of the text!),
//! then fills in the actual documentation content from the CLI doc fragments,
//! and the command help texts generated by clap.
//! The doc fragments are doc comments in the source code marked with
//! `[cli-doc] <fragment-id>`, right next to the code they document.

use std::{collections::HashSet, path::PathBuf, str::FromStr, sync::LazyLock, time::Duration};

use anyhow::{Context, Result};
use clap::{CommandFactory, builder::Styles};
use filen_macros::extract_cli_doc_fragments;
use tiny_http::{Header, Request, Response};

use crate::{
	CliArgs,
	commands::{
		auth_cmds, fs_cmds, misc_cmds, notes_cmds, public_links_cmds, rclone_cmds, search_cmd,
		shell_cmds, sync_cmd, transfer_cmds,
	},
	interrupt,
	ui::UI,
};

extract_cli_doc_fragments!();

/// One piece of a doc section. Each command module exports the pieces that document its
/// commands (`DOCS` consts), and [`DOC_OUTLINE`] places them into sections.
#[derive(Debug)]
pub(crate) enum DocElement {
	Heading1(&'static str),
	DocFragment(&'static str),
	CommandHelp(&'static str),
	GlobalOptions,
}

#[derive(Debug, Clone)]
enum ParsedDocElement {
	Heading1 { text: String },
	DocFragment { text: String },
	CommandHelp { command: Box<clap::Command> },
	GlobalOptions,
}

#[derive(Debug)]
struct DocSection {
	id: &'static str,
	title: &'static str,
	/// The section's elements, in order: its parts are concatenated.
	parts: &'static [&'static [DocElement]],
}

impl DocSection {
	fn elements(&self) -> impl Iterator<Item = &'static DocElement> {
		self.parts.iter().flat_map(|part| part.iter())
	}
}

#[derive(Debug, Clone)]
struct ParsedDocSection {
	id: String,
	title: String,
	elements: Vec<ParsedDocElement>,
}

const USAGE_INTRO_DOCS: &[DocElement] = &[
	DocElement::DocFragment("main-usage"),
	DocElement::Heading1("Options"),
	DocElement::GlobalOptions,
	DocElement::Heading1("Updates"),
	DocElement::DocFragment("updates"),
	DocElement::Heading1("Config directory"),
	DocElement::DocFragment("config-dir"),
	DocElement::Heading1("Log files"),
	DocElement::DocFragment("log-files"),
	DocElement::Heading1("Exit codes"),
	DocElement::DocFragment("exit-codes"),
	DocElement::Heading1("Commands"),
];

/// The sections of the docs, in order. Every command and doc fragment must appear exactly once.
const DOC_OUTLINE: &[DocSection] = &[
	DocSection {
		id: "usage",
		title: "Usage",
		parts: &[USAGE_INTRO_DOCS, misc_cmds::DOCS, shell_cmds::DOCS],
	},
	DocSection {
		id: "auth",
		title: "Authentication",
		parts: &[auth_cmds::DOCS],
	},
	DocSection {
		id: "access-files",
		title: "Accessing Files",
		parts: &[
			fs_cmds::BROWSING_DOCS,
			search_cmd::DOCS,
			fs_cmds::ORGANIZING_DOCS,
			public_links_cmds::DOCS,
		],
	},
	DocSection {
		id: "transfer-files",
		title: "Transferring Files",
		parts: &[transfer_cmds::DOCS, sync_cmd::DOCS],
	},
	DocSection {
		id: "notes",
		title: "Notes",
		parts: &[notes_cmds::DOCS],
	},
	DocSection {
		id: "managed-rclone",
		title: "Managed Rclone",
		parts: &[rclone_cmds::DOCS],
	},
];

const MAIN_SECTION: &str = "usage";
static PARSED_DOC_OUTLINE: LazyLock<Result<Vec<ParsedDocSection>>> = LazyLock::new(|| {
	// parse doc elements
	let mut commands = CliArgs::command();
	let mut used_commands = HashSet::new();
	let cli_doc_fragments = get_cli_doc_fragments();
	let mut used_doc_fragments = HashSet::new();
	let mut used_global_options = false;
	let parsed_outline = DOC_OUTLINE
		.iter()
		.map(|section| {
			let parsed_elements = section
				.elements()
				.map(|element| match element {
					DocElement::Heading1(text) => Ok(ParsedDocElement::Heading1 {
						text: text.to_string(),
					}),
					DocElement::DocFragment(fragment_id) => {
						if let Some(fragment) = cli_doc_fragments
							.iter()
							.find(|fragment| fragment.id == *fragment_id)
						{
							used_doc_fragments.insert(fragment.id.clone());
							Ok(ParsedDocElement::DocFragment {
								text: fragment
									.content
									.replace("{{VERSION}}", env!("CARGO_PKG_VERSION")),
							})
						} else {
							Err(anyhow::anyhow!(
								"Doc fragment with id '{}' not found",
								fragment_id
							))
						}
					}
					DocElement::CommandHelp(command) => {
						if let Some(command) = commands.find_subcommand_mut(command) {
							used_commands.insert(command.get_name().to_string());
							Ok(ParsedDocElement::CommandHelp {
								command: Box::new(command.clone()),
							})
						} else {
							Err(anyhow::anyhow!(
								"Command '{}' not found in CLI structure",
								command
							))
						}
					}
					DocElement::GlobalOptions => {
						used_global_options = true;
						Ok(ParsedDocElement::GlobalOptions)
					}
				})
				.collect::<Result<Vec<ParsedDocElement>>>()
				.with_context(|| {
					format!("Failed to parse doc elements for section '{}'", section.id)
				})?;
			Ok(ParsedDocSection {
				id: section.id.to_string(),
				title: section.title.to_string(),
				elements: parsed_elements,
			})
		})
		.collect::<Result<Vec<ParsedDocSection>>>()?;

	// ensure that all doc fragments, commands and global options were used
	let unused_doc_fragments = cli_doc_fragments
		.iter()
		.map(|fragment| &fragment.id)
		.filter(|id| !used_doc_fragments.contains(id.as_str()))
		.collect::<Vec<&String>>();
	if !unused_doc_fragments.is_empty() {
		return Err(anyhow::anyhow!(
			"Some CLI doc fragments were not used in the markdown docs: {:?}",
			unused_doc_fragments
		));
	}
	// hidden commands only say what replaced them, so they have no docs
	let unused_commands = commands
		.get_subcommands()
		.filter(|cmd| !cmd.is_hide_set())
		.map(|cmd| cmd.get_name().to_string())
		.filter(|name| !used_commands.contains(name))
		.collect::<Vec<String>>();
	if !unused_commands.is_empty() {
		return Err(anyhow::anyhow!(
			"Some CLI commands were not documented in the markdown docs: {:?}",
			unused_commands
		));
	}
	if !used_global_options {
		return Err(anyhow::anyhow!(
			"Global CLI options were not documented in the markdown docs"
		));
	}

	// ensure ids are unique among doc fragments and commands
	// (sections are allowed to have the same id, then they take precedence)
	let mut ids = DOC_OUTLINE
		.iter()
		.flat_map(|section| {
			section.elements().filter_map(|element| match element {
				DocElement::DocFragment(fragment_id) => Some(*fragment_id),
				DocElement::CommandHelp(command_id) => Some(*command_id),
				_ => None,
			})
		})
		.collect::<Vec<&'static str>>();
	ids.sort();
	for i in 1..ids.len() {
		if ids[i] == ids[i - 1] {
			return Err(anyhow::anyhow!("Duplicate doc id found: '{}'", ids[i]));
		}
	}

	Ok(parsed_outline)
});

// markdown docs

pub(crate) fn generate_markdown_docs() -> Result<()> {
	let output_dir = PathBuf::from("filen-cli-markdown-docs");
	std::fs::create_dir_all(&output_dir).context("Failed to create markdown docs output dir")?;
	PARSED_DOC_OUTLINE
		.as_ref()
		.map_err(|e| anyhow::anyhow!("Failed to parse CLI doc outline: {}", e))?
		.iter()
		.enumerate()
		.try_for_each(|(i, section)| {
			let markdown_content = format_markdown_section(section);
			std::fs::write(
				output_dir.join(format!("{:02}-{}.md", i + 1, section.id)),
				markdown_content,
			)
			.with_context(|| format!("Failed to write markdown doc file '{}'", section.id))
		})?;
	Ok(())
}

fn format_markdown_section(section: &ParsedDocSection) -> String {
	let elements = section
		.elements
		.iter()
		.map(|element| match element {
			ParsedDocElement::Heading1 { text } => format!("## {}", text),
			ParsedDocElement::DocFragment { text } => text.to_string(),
			ParsedDocElement::CommandHelp { command } => {
				format_markdown_command_help(&mut command.clone())
			}
			ParsedDocElement::GlobalOptions => CliArgs::command()
				.clone()
				.help_template("{options}")
				.render_help()
				.to_string()
				.lines()
				.map(|l| {
					if l.trim().starts_with("-") {
						format!("- `{}`", l.trim())
					} else {
						format!("  {}", l.trim())
					}
				})
				.collect::<Vec<String>>()
				.join("  \n"),
		})
		.collect::<Vec<String>>();
	let mut markdown_content = String::new();
	markdown_content.push_str(&format!("# {}\n\n", section.title));
	markdown_content
		.push_str("<!-- This file is generated by filen-cli. Do not edit it directly! -->\n\n");
	markdown_content.push_str(&elements.join("\n\n"));
	markdown_content
}

fn format_markdown_command_help(cmd: &mut clap::Command) -> String {
	let render_help_text_template = |template: &'static str| {
		cmd.clone()
			.styles(if console::colors_enabled() {
				Styles::styled()
					.literal(anstyle::Style::new())
					.header(anstyle::Style::new())
					.usage(anstyle::Style::new())
			} else {
				Styles::plain()
			})
			.help_template(template)
			.render_help()
			.to_string()
	};
	let usage = render_help_text_template("{usage}");
	let about = render_help_text_template("{about}");
	let args = render_help_text_template("{positionals}\n{options}")
		.lines()
		.filter(|l| !l.contains("--help")) // filter out help flag line that is erraneously included by clap
		.map(|l| {
			let parts = l
				.trim()
				.split("  ")
				.map(|part| part.trim())
				.filter(|part| !part.is_empty())
				.collect::<Vec<&str>>();
			if parts.len() == 2 {
				format!("  \n> 🠊 `{}` {}", parts[0], parts[1])
			} else {
				log::warn!(
					"Unexpected args line format: '{}' for command '{}' (maybe it misses a description)",
					l,
					cmd.get_name()
				);
				format!("  \n> 🠊 {}", l.trim())
			}
		})
		.collect::<Vec<_>>();
	format!(
		"> `{}`  \n> {}{}",
		usage.trim(),
		about.trim(),
		args.join("")
	)
}

// in-app docs

pub(crate) fn get_help_topics() -> Result<Vec<String>> {
	let parsed_doc_outline = PARSED_DOC_OUTLINE
		.as_ref()
		.map_err(|e| anyhow::anyhow!("Failed to parse CLI doc outline: {}", e))?;
	Ok(parsed_doc_outline
		.iter()
		.map(|section| section.id.clone())
		.chain(
			get_cli_doc_fragments()
				.iter()
				.map(|fragment| fragment.id.clone()),
		)
		.chain(
			CliArgs::command()
				.get_subcommands()
				.flat_map(|c| c.get_name_and_visible_aliases())
				.map(|s| s.to_string()),
		)
		.collect::<Vec<String>>())
}

pub(crate) fn print_in_app_docs(
	ui: &mut UI,
	section_or_command_or_topic: Option<String>,
) -> Result<()> {
	let parsed_doc_outline = PARSED_DOC_OUTLINE
		.as_ref()
		.map_err(|e| anyhow::anyhow!("Failed to parse CLI doc outline: {}", e))?;
	let command_or_topic = section_or_command_or_topic.unwrap_or(String::from(MAIN_SECTION));
	if let Some(section) = parsed_doc_outline.iter().find(|s| s.id == command_or_topic) {
		// doc section
		ui.print(&UI::format_text_heading(&section.title));
		ui.print("");
		let elements = section
			.elements
			.iter()
			.map(|element| match element {
				ParsedDocElement::Heading1 { text } => UI::format_text_heading(text),
				ParsedDocElement::DocFragment { text } => text.to_string(),
				ParsedDocElement::CommandHelp { command } => {
					UI::format_text_blockquote(&UI::format_command_help(&mut command.clone()))
				}
				ParsedDocElement::GlobalOptions => UI::format_global_options_help(),
			})
			.collect::<Vec<String>>();
		ui.print(&elements.join("\n\n"));

		// print table of contents for main section
		if command_or_topic == MAIN_SECTION {
			ui.print("");
			ui.print(&UI::format_text_heading("More help topics"));
			ui.print("");
			ui.print(
				&parsed_doc_outline
					.iter()
					.filter_map(|section| {
						if section.id != MAIN_SECTION {
							Some(format!(
								"{}  {} {}",
								console::style(&section.title).underlined(),
								console::style("→").dim(),
								console::style(format!("help {}", section.id)).green()
							))
						} else {
							None
						}
					})
					.collect::<Vec<String>>()
					.join("\n"),
			);
		}
	} else if let Some(doc_fragment) = get_cli_doc_fragments()
		.iter()
		.find(|fragment| fragment.id == command_or_topic)
	{
		// doc fragment
		ui.print(&doc_fragment.content);
	} else if let Some(command) = CliArgs::command().find_subcommand_mut(&command_or_topic) {
		// command help
		ui.print(&UI::format_command_help(&mut command.clone()));
	} else {
		return Err(UI::failure(&format!(
			"No help found for '{}'",
			command_or_topic
		)));
	}

	Ok(())
}

// markdown docs rendered to HTML and served in-app

/// How long the docs server waits for a request before it looks for Ctrl-C again.
const DOCS_SERVER_POLL: Duration = Duration::from_millis(200);

pub(crate) fn serve_markdown_docs_as_html(ui: &mut UI) -> Result<()> {
	let parsed_doc_outline = PARSED_DOC_OUTLINE
		.as_ref()
		.map_err(|e| anyhow::anyhow!("Failed to parse CLI doc outline: {}", e))?;

	let server_port = port_check::free_local_ipv4_port()
		.ok_or(anyhow::anyhow!("Failed to find free port for docs server"))?;

	let server = tiny_http::Server::http(format!("localhost:{}", server_port))
		.map_err(|e| anyhow::anyhow!("Failed to start docs HTTP server: {}", e))?;

	// Ctrl-C stops the server: the command blocks its thread while it serves, so nothing could
	// cancel it, and it looks for Ctrl-C between requests instead
	let mut ctrl_c = interrupt::own();
	ui.print_success(&format!(
		"Serving documentation at http://localhost:{} (press Ctrl-C to stop)",
		server_port
	));
	if let Err(e) = open::that(format!("http://localhost:{}", server_port)) {
		log::warn!("Failed to open docs URL in browser automatically: {}", e);
	}

	serve_until(
		&server,
		|| ctrl_c.was_pressed(),
		|request| respond_with_section(parsed_doc_outline, request),
	)
}

/// Answers the requests to `server` with `respond` until `stopped` says to stop, which it is asked
/// at least every [`DOCS_SERVER_POLL`].
fn serve_until(
	server: &tiny_http::Server,
	mut stopped: impl FnMut() -> bool,
	mut respond: impl FnMut(Request) -> Result<()>,
) -> Result<()> {
	while !stopped() {
		if let Some(request) = server
			.recv_timeout(DOCS_SERVER_POLL)
			.context("Failed to receive a docs HTTP request")?
		{
			respond(request)?;
		}
	}
	Ok(())
}

/// Answers `request` with the doc section its path names, rendered as HTML.
fn respond_with_section(parsed_doc_outline: &[ParsedDocSection], request: Request) -> Result<()> {
	let Some(section) = parsed_doc_outline.iter().find(|section| {
		(request.url() == format!("/{}", section.id))
			|| (request.url() == "/" && section.id == MAIN_SECTION)
	}) else {
		return request
			.respond(Response::from_string("Section not found"))
			.context("Failed to respond to docs HTTP request");
	};

	// customize main section with title and table of contents
	let section = {
		let mut section = section.clone();
		if section.id == MAIN_SECTION {
			section.title = format!("Filen CLI v{}", env!("CARGO_PKG_VERSION"));
			section.elements.push(ParsedDocElement::Heading1 {
				text: "More help topics".to_string(),
			});
			section.elements.push(ParsedDocElement::DocFragment {
				text: parsed_doc_outline
					.iter()
					.filter_map(|section| {
						if section.id != MAIN_SECTION {
							Some(format!("- [{}](/{})", section.title, section.id))
						} else {
							None
						}
					})
					.collect::<Vec<String>>()
					.join("\n"),
			});
		}
		section
	};

	let markdown = format_markdown_section(&section);
	let html = comrak::markdown_to_html(
		&markdown,
		&comrak::Options {
			extension: comrak::options::Extension::builder().autolink(true).build(),
			render: comrak::options::Render::builder().build(),
			parse: comrak::options::Parse::builder().build(),
		},
	);
	let html = format!("{}<body>{}</body>", HTML_STYLE, html);
	let html = html.replace("🠊", "&#129034;");

	// note: Of course, it's actually not the most efficient way to generate HTML based on the intermediate markdown,
	// and we could probably save some binary size and make it look better by generating HTML directly from the doc
	// fragments, but for now, this is just easier to implement and maintain, and good enough.

	request
		.respond(
			Response::from_string(html)
				.with_header(Header::from_str("Content-Type: text/html").unwrap()),
		)
		.context("Failed to respond to docs HTTP request")
}

// AI-generated docs styles, might change later
// since this is not very critical, it's okay for now that it's not checked at compile time etc
// It loads nothing from elsewhere: a page served from this machine makes no outside request, so
// Inter and JetBrains Mono are used only where they are installed, with the system fonts next.
const HTML_STYLE: &str = "
<style>
:root{
	--bg:#0b0f13; /* very dark */
	--panel:#0f1418;
	--muted:#b4bcc7;
	--text:#f1f6fc;
	--accent:#7aa2ff;
	--underline:#3a4248;
	--code-bg:#2b3138;
}

*{box-sizing:border-box}
body{
	margin:24px; font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
	background:linear-gradient(180deg,var(--bg),#071018 120%);
	color:var(--text); line-height:1.5; font-size:15px;
}

h1,h2,h3,h4{color:var(--text); margin:0 0 12px 0; font-weight:700}
h1{font-size:28px}
h2{font-size:20px; margin-top:18px}

/* headers with gray underline */
h1,h2{
	padding-bottom:4px;
	border-bottom:3px solid var(--underline);
}

p{margin:10px 0; color:var(--muted)}

ul{margin:8px 0 16px 0px; padding-left: 30px; color:var(--muted)}
li{margin:8px 0}

code{background:var(--code-bg); color:var(--muted); font-family:'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, monospace; padding:2px 6px; border-radius:6px}

/* code blocks and samples */
pre, .code-block{background:var(--code-bg); color:var(--text); padding:12px; border-radius:8px; overflow:auto}

blockquote{border-left:2px solid #616a74; padding:5px 12px; background:rgba(97,106,116,0.1); color:var(--text); margin:12px 0; border-radius:6px}

a{color:var(--accent); text-decoration:none}
a:hover{text-decoration:underline}

/* small utility */
.muted{color:var(--muted)}

/* responsive */
@media (max-width:640px){body{margin:14px;font-size:14px} h1{font-size:22px}}
</style>
";

#[cfg(test)]
mod tests {
	use std::{
		cell::RefCell,
		io::{Read as _, Write as _},
		net::TcpStream,
		thread,
	};

	use super::*;

	/// A docs server on a free port of the loopback interface, and its address.
	fn local_server() -> (tiny_http::Server, std::net::SocketAddr) {
		let server = tiny_http::Server::http("127.0.0.1:0").unwrap();
		let address = server.server_addr().to_ip().unwrap();
		(server, address)
	}

	#[test]
	fn the_usage_section_documents_the_config_directory_and_the_log_files() {
		let outline = PARSED_DOC_OUTLINE.as_ref().unwrap();
		let usage = outline.iter().find(|s| s.id == MAIN_SECTION).unwrap();
		let fragments = get_cli_doc_fragments();
		for id in ["config-dir", "log-files", "updates"] {
			let fragment = fragments.iter().find(|f| f.id == id).unwrap();
			assert!(
				usage.elements.iter().any(|element| matches!(
					element,
					ParsedDocElement::DocFragment { text } if *text == fragment.content
				)),
				"{id}"
			);
		}
	}

	#[test]
	fn the_html_docs_load_nothing_from_elsewhere() {
		for external in ["http://", "https://", "@import", "url("] {
			assert!(!HTML_STYLE.contains(external), "{external}");
		}
	}

	#[test]
	fn the_docs_server_stops_when_asked_to_with_no_request() {
		let (server, _) = local_server();
		let mut asked = 0;
		serve_until(
			&server,
			|| {
				asked += 1;
				asked > 2
			},
			|_| panic!("no request was sent"),
		)
		.unwrap();
		assert_eq!(asked, 3);
	}

	#[test]
	fn the_docs_server_answers_requests_until_it_is_stopped() {
		let (server, address) = local_server();
		let client = thread::spawn(move || {
			let mut stream = TcpStream::connect(address).unwrap();
			stream
				.write_all(b"GET /some-section HTTP/1.0\r\n\r\n")
				.unwrap();
			let mut response = String::new();
			stream.read_to_string(&mut response).unwrap();
			response
		});
		// read by one closure and written by the other
		let answered = RefCell::new(Vec::new());
		serve_until(
			&server,
			|| !answered.borrow().is_empty(),
			|request| {
				answered.borrow_mut().push(request.url().to_owned());
				request
					.respond(Response::from_string("served"))
					.context("respond")
			},
		)
		.unwrap();
		assert_eq!(answered.into_inner(), ["/some-section"]);
		assert!(client.join().unwrap().ends_with("served"));
	}

	#[test]
	fn doc_outline_documents_every_command_and_fragment_once() {
		if let Err(e) = PARSED_DOC_OUTLINE.as_ref() {
			panic!("the doc outline is incomplete: {e:#}");
		}
	}
}
